export function SvgIcon({ name, width = 24, height = 24, color, style }) {
  let xml = SVG_ICONS[name];
  
  if (SvgXml && xml) {
    if (color) {
      xml = xml.replace(/fill="#[0-9a-fA-F]{6}"/g, `fill="${color}"`);
    }
    return <SvgXml xml={xml} width={width} height={height} style={style} />;
  }

  // Fallback vector icon
  const vectorMap = {
    ic_tab_home: { type: 'ion', icon: 'home-outline' },
    ic_tab_home_active: { type: 'ion', icon: 'home' },
    ic_tab_all_apps: { type: 'ion', icon: 'folder-outline' },
    ic_tab_all_apps_active: { type: 'ion', icon: 'folder' },
    ic_tab_gold: { type: 'ion', icon: 'radio-button-off' },
    ic_tab_gold_active: { type: 'ion', icon: 'radio-button-on' },
    ic_tab_game: { type: 'ion', icon: 'game-controller-outline' },
    ic_tab_game_active: { type: 'ion', icon: 'game-controller' },
    ic_tab_profile: { type: 'ion', icon: 'person-outline' },
    ic_tab_profile_active: { type: 'ion', icon: 'person' },
    ic_app_approve_now: { type: 'ion', icon: 'create-outline' },
    ic_app_reward: { type: 'ion', icon: 'medal-outline' },
    ic_app_discipline: { type: 'mci', icon: 'gavel' },
    ic_app_learning: { type: 'ion', icon: 'school-outline' },
    ic_app_my_tasks: { type: 'ion', icon: 'checkbox-outline' },
    ic_app_fpt_care: { type: 'ion', icon: 'card-outline' },
    ic_app_events: { type: 'mci', icon: 'party-popper' },
    ic_app_survey: { type: 'ion', icon: 'laptop-outline' },
    ic_app_fpt_dating: { type: 'ion', icon: 'heart-half-outline' },
    ic_app_payslip: { type: 'ion', icon: 'wallet-outline' },
    ic_app_birthday: { type: 'mci', icon: 'cake' },
    ic_app_news: { type: 'ion', icon: 'newspaper-outline' },
    ic_app_star_ave: { type: 'ion', icon: 'ribbon-outline' },
    ic_app_employee_info: { type: 'ion', icon: 'folder-open-outline' },
    ic_app_game: { type: 'ion', icon: 'people-outline' },
    ic_camera_avatar: { type: 'ion', icon: 'camera' },
    ic_menu_my_profile: { type: 'ion', icon: 'person' },
    ic_menu_settings: { type: 'ion', icon: 'settings-sharp' },
    ic_menu_support: { type: 'ion', icon: 'life-buoy' },
    ic_menu_faq: { type: 'ion', icon: 'help-circle' },
    ic_menu_admin: { type: 'ion', icon: 'shield-checkmark' },
    ic_menu_logout: { type: 'ion', icon: 'log-out' },
    ic_chevron_right: { type: 'ion', icon: 'chevron-forward' },
    ic_search: { type: 'ion', icon: 'search' },
    ic_grid: { type: 'ion', icon: 'grid-outline' },
  };

  const fallback = vectorMap[name] || { type: 'ion', icon: 'help-circle-outline' };
  const isTabActive = name && name.endsWith('_active');
  const iconColor = color || (isTabActive ? '#FFFFFF' : '#0066CC');

  let iconNode = null;
  if (fallback.type === 'mci') {
    iconNode = <MaterialCommunityIcons name={fallback.icon} size={isTabActive ? 16 : width} color={iconColor} style={style} />;
  } else {
    iconNode = <Ionicons name={fallback.icon} size={isTabActive ? 16 : width} color={iconColor} style={style} />;
  }

  if (isTabActive) {
    return (
      <View
        style={[
          {
            width: width || 28,
            height: height || 28,
            borderRadius: (width || 28) / 2,
            backgroundColor: '#0066CC',
            justify: 'center',
            alignItems: 'center',
          },
          style,
        ]}
      >
        {iconNode}
      </View>
    );
  }

  return iconNode;
}

export default SvgIcon;
